/* Microfix 3.8.27: active chat header shows provider identity only */
.bridge-title .provider-head-avatar{width:35px;height:35px;border-radius:11px;display:grid;place-items:center;background:color-mix(in srgb,var(--surface-2) 88%,transparent);border:1px solid color-mix(in srgb,var(--agent-color,#8b5cf6) 36%,var(--line));box-shadow:none;padding:6px;overflow:hidden}
.bridge-title .provider-head-avatar img{display:block;width:100%;height:100%;object-fit:contain}
.bridge-title small[hidden]{display:none!important}
.bridge-title:has(.provider-head-avatar) strong{margin-top:0;font-size:14px;font-weight:800}

/* Microfix 3.8.28: updater must never cover the app header */
.update-popover{position:fixed!important;top:88px!important;left:112px!important;max-height:calc(100vh - 104px);overflow:auto}
@media(max-width:900px){.update-popover{left:12px!important;right:12px!important;width:auto!important;top:82px!important}}
